const e="olive-mgocsm-delhi-diocese-talents",h=2025,t="Source: Olive 2025 Rules and Regulations circular of the MGOCSM Delhi Diocese Committee, signed by the Vice President. It prints no entry fee, no prize list, no street address for the venue and no phone numbers; the contacts are named but their numbers are not printed. The tentative schedule (kept as the Schedule variable) may change. Solo Instrumental is one printed event with two categories and is two competitions here, with the same rules.",n={Title:"Olive Rules & Criteria",Subtitle:"Olive 2025, the Celebration of Talents of the MGOCSM Delhi Diocese Committee, for units of the Diocese, 18 to 25 years.",NoticeTitle:"Please Read Before Registering",Notice:"Registration is one form per unit, sent by the Unit Secretary by {{RegistrationDeadline}}. No registrations are accepted after the deadline. Event day: {{EventDate}}.",Notes:["The schedule printed in the circular is tentative and can change.","Complaints about the rules must reach the Vice President by {{RulesQueryDeadline}}."],Sections:[{Key:"general",Title:"General Guidelines",Items:["Olive 2025 is held in physical mode, at {{Venue}}.","Events run at the same time at several venues. The organising committee may change the order of performances if a participant's schedule clashes.","All events are marked out of 100.","The decision of the judges is final and binding for all events.","The time given to each event and performance must be kept strictly. Marks are deducted for going over the time limit."]},{Key:"eligibility",Title:"Who May Enter",Items:["All participants must be subscribing MGOCSM members of their unit.","Details of every participant must be updated on the MGOCSM online database, which is open until {{RegistrationDeadline}}. The Diocesan Committee cross-checks the participants' details.","Participants must be 18 to 25 years old, born between 31 August 1999 and 31 August 2007.","The lower limit is passing Class 12 in Sunday School, or completing 18 years on the first day of Olive, whichever is earlier.","A participant cannot register for both events of a paired event that runs at the same time at separate venues: Essay Writing and Poster Making, or Solo Instrumental and Extempore.","Each unit sends two participants for Solo Song, one participant for each other individual event, one team of two for Bible Quiz, and one team for each of Group Song and Street Play."]},{Key:"registration",Title:"How to Register",Items:["Olive 2025 has a single registration form, sent to the Unit Secretaries' WhatsApp group on {{FormReleaseDate}}.","The Unit Secretary fills in the names of all participants, gets the form signed by the Unit President, and sends it by email to the Diocesan MGOCSM Committee at {{RegistrationEmail}}.","The form must be sent by {{RegistrationDeadline}}. No registrations are accepted after the deadline.","After cross-checking with the database, the Diocesan Committee gives the units and participants their chest numbers for the event.","Chest numbers are given on the day of the event at the registration desk. The Unit Secretaries are responsible for this.","Each participant gets an individual badge number on the day of Olive.","A booklet of Bible verses and the Bible Quiz syllabus are sent to the Unit Secretaries on {{MaterialsDate}}. The Orthodox Apologetics topic is given on the same date.","For any event query, contact {{SecretaryContact}} or {{CulturalSecretaryContact}}."]},{Key:"conduct",Title:"Conduct and Disqualification",Items:["Every participant must wear the badge number during the events. Not following this instruction may lead to disqualification.","Participants must make sure their chest number is clearly visible to the judges in on-stage events, and clearly written in off-stage events.","A participant is disqualified if the chest number is wrong, missing or not visible.","Participants must not write their name, parish name or anything else that shows their identity anywhere during the events."]},{Key:"judging",Title:"Judging",Items:["All events are marked out of 100.","The decision of the judges is final and binding."]},{Key:"complaints",Title:"Queries About the Rules",Items:["A Unit Secretary who has a concern about the rules and regulations must send an email to {{RegistrationEmail}} for the attention of the Diocesan MGOCSM Vice President by {{RulesQueryDeadline}}."]},{Key:"dates",Title:"Important Dates",Items:["Registration form sent to Unit Secretaries: {{FormReleaseDate}}.","Last date to register and to update the online database: {{RegistrationDeadline}}.","Rules query deadline: {{RulesQueryDeadline}}.","Presentation file for Orthodox Apologetics due: {{PptDeadline}}.","Event day: {{EventDate}}."]},{Key:"venue",Title:"Venue",Items:["Olive 2025 is held at {{Venue}}. Participants must stay inside the school premises during Photography."]},{Key:"points",Title:"Championship Points",Items:["In every event (Solo Song, Essay Writing, Poster Making, Solo Instrumental, Photography, Bible Verse Writing, Bible Quiz, Orthodox Apologetics, Mono Act, Group Song, Street Play and Extempore) the first position gets 5 points, the second 4 points and the third 3 points."]}],Documents:[{Title:"Olive 2025 Rules and Regulations",Url:"https://www.scribd.com/document/905254873/Olive-2025-Rules-and-Regulations"}]},i=[],a=[],o=JSON.parse(`[{"Title":"Solo Song","Source":"Solo Song guidelines","Sections":{"About":["Each unit sends two participants, one male and one female. If a unit has too few participants it may send two males or two females, with a separate consent form signed by the Unit President.","Winners are declared separately for Solo Song Male and Solo Song Female."],"TimeAndFormat":["Each performance is 3 minutes. A warning bell rings at 2 minutes 30 seconds.","Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks."],"Rules":["The song must be a Christian devotional song.","The song can be in one language only: English, Hindi or Malayalam."],"Allowed":null,"NotAllowed":["No musical instrument or karaoke is allowed."],"Judging":["Melody, Dynamics, Intonation and Voice Modulation: 40%.","Breath Support: 20%.","Rhythm: 30%.","Expression: 10%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Each unit sends two participants, one male and one female. If a unit has too few participants it may send two males or two females, with a separate consent form signed by the Unit President.\\n- Winners are declared separately for Solo Song Male and Solo Song Female.\\n\\n## Time and format\\n- Each performance is 3 minutes. A warning bell rings at 2 minutes 30 seconds.\\n- Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.\\n\\n## Rules\\n- The song must be a Christian devotional song.\\n- The song can be in one language only: English, Hindi or Malayalam.\\n\\n## Not allowed\\n- No musical instrument or karaoke is allowed.\\n\\n## Judging\\n- Melody, Dynamics, Intonation and Voice Modulation: 40%.\\n- Breath Support: 20%.\\n- Rhythm: 30%.\\n- Expression: 10%.\\n- The decision of the judges is final and binding."},{"Title":"Photography","Source":"Photography guidelines","Sections":{"About":["One participant per unit."],"TimeAndFormat":["Each participant has 5 hours in total to take the photo and submit the entry. Submissions after the deadline are not accepted."],"Rules":["The theme is given on the day of the event, 31 August 2025. It is chosen by drawing lots in front of the participants.","Photographs can only be taken inside the school premises. Participants may not leave the school premises under any circumstance.","The original photographs are copied to a system as instructed on the day, in the presence of the judge.","The photo must be in JPEG or JPG format.","Each participant submits one photograph for evaluation, with the RAW file that holds the original EXIF data for checking.","Each participant gives a description of the photograph of under 50 words in the Google form link that is provided. The link closes as soon as the photography event closes.","The photo must be the participant's own original work and must fit the theme."],"Allowed":["Basic editing, such as colour enhancement, filters and cropping, if it does not affect the authenticity of the photo.","Digital SLR or non-SLR cameras and mobile phones."],"NotAllowed":["Advanced editing that creates illusions, deceptions or manipulation, adds or removes significant elements, or mixes or merges two or more images.","Breaking any of these rules leads to disqualification."],"Judging":["Appropriateness to the Theme and Depiction of the Theme: 50%.","Composition and Lighting: 30%.","Creativity: 20%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n\\n## Time and format\\n- Each participant has 5 hours in total to take the photo and submit the entry. Submissions after the deadline are not accepted.\\n\\n## Rules\\n- The theme is given on the day of the event, 31 August 2025. It is chosen by drawing lots in front of the participants.\\n- Photographs can only be taken inside the school premises. Participants may not leave the school premises under any circumstance.\\n- The original photographs are copied to a system as instructed on the day, in the presence of the judge.\\n- The photo must be in JPEG or JPG format.\\n- Each participant submits one photograph for evaluation, with the RAW file that holds the original EXIF data for checking.\\n- Each participant gives a description of the photograph of under 50 words in the Google form link that is provided. The link closes as soon as the photography event closes.\\n- The photo must be the participant's own original work and must fit the theme.\\n\\n## Allowed\\n- Basic editing, such as colour enhancement, filters and cropping, if it does not affect the authenticity of the photo.\\n- Digital SLR or non-SLR cameras and mobile phones.\\n\\n## Not allowed\\n- Advanced editing that creates illusions, deceptions or manipulation, adds or removes significant elements, or mixes or merges two or more images.\\n- Breaking any of these rules leads to disqualification.\\n\\n## Judging\\n- Appropriateness to the Theme and Depiction of the Theme: 50%.\\n- Composition and Lighting: 30%.\\n- Creativity: 20%.\\n- The decision of the judges is final and binding."},{"Title":"Mono Act","Source":"Mono Act guidelines","Sections":{"About":["One participant per unit.","The participant enacts a Biblical scene from the Old or the New Testament."],"TimeAndFormat":["The whole performance must not exceed 4 minutes. A warning bell rings at 3 minutes 30 seconds.","The timer starts as soon as the chest number is called.","Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks."],"Rules":["The script must stay true to the Biblical narration of the scene. No remakes are allowed.","The language can be Hindi, English or Malayalam.","Dialogue is delivered live on stage.","Props (one prop per participant) and costumes can be used, but no marks are given for them. Only the acting performance is evaluated.","Props are arranged by the participant and managed only by the participant. No outside help is allowed."],"Allowed":null,"NotAllowed":["No music or pre-recorded audio.","Mime is not allowed."],"Judging":["Dialogue Delivery and Voice Modulation: 30%.","Acting Skills, Gestures and Movements: 40%.","Content and Expressions: 30%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n- The participant enacts a Biblical scene from the Old or the New Testament.\\n\\n## Time and format\\n- The whole performance must not exceed 4 minutes. A warning bell rings at 3 minutes 30 seconds.\\n- The timer starts as soon as the chest number is called.\\n- Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.\\n\\n## Rules\\n- The script must stay true to the Biblical narration of the scene. No remakes are allowed.\\n- The language can be Hindi, English or Malayalam.\\n- Dialogue is delivered live on stage.\\n- Props (one prop per participant) and costumes can be used, but no marks are given for them. Only the acting performance is evaluated.\\n- Props are arranged by the participant and managed only by the participant. No outside help is allowed.\\n\\n## Not allowed\\n- No music or pre-recorded audio.\\n- Mime is not allowed.\\n\\n## Judging\\n- Dialogue Delivery and Voice Modulation: 30%.\\n- Acting Skills, Gestures and Movements: 40%.\\n- Content and Expressions: 30%.\\n- The decision of the judges is final and binding."},{"Title":"Group Song","Source":"Group Song guidelines (code GS)","Sections":{"About":["Competition code: GS.","The song must be a Christian devotional song, in one language only: English, Hindi or Malayalam."],"TimeAndFormat":["Each performance is 7 minutes, including stage setup. The first warning bell rings at 6 minutes.","The timer starts after the last member of the choir team enters the stage. Setting up instruments and microphones starts only after the timer begins.","The timer stops as soon as the music or song stops. The team must tell the Diocesan Committee about any planned pauses in the song.","Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.","The order of performance is decided by drawing lots and announced at the beginning. Chest numbers are called well in advance, and the next team stays ready while one team performs."],"Rules":["A team has at least 3 members, not counting the instrumentalist, and at most 20 members, counting instrumentalists.","Any musical instrument can be used, up to 2 instruments.","Only the registered members may perform. No member replacement is allowed.","The organisers do not provide any instruments."],"Allowed":["Keyboard MIDI as accompaniment track, with no human voice or vocal parts."],"NotAllowed":["MP3 and karaoke tracks."],"Judging":["Melody, Dynamics, Intonation and Voice Modulation: 40%.","Breath Support: 20%.","Rhythm and Synchronization: 30%.","Expression: 10%.","The judge inspects the keyboard and the accompaniment track on the event day.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Competition code: GS.\\n- The song must be a Christian devotional song, in one language only: English, Hindi or Malayalam.\\n\\n## Time and format\\n- Each performance is 7 minutes, including stage setup. The first warning bell rings at 6 minutes.\\n- The timer starts after the last member of the choir team enters the stage. Setting up instruments and microphones starts only after the timer begins.\\n- The timer stops as soon as the music or song stops. The team must tell the Diocesan Committee about any planned pauses in the song.\\n- Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.\\n- The order of performance is decided by drawing lots and announced at the beginning. Chest numbers are called well in advance, and the next team stays ready while one team performs.\\n\\n## Rules\\n- A team has at least 3 members, not counting the instrumentalist, and at most 20 members, counting instrumentalists.\\n- Any musical instrument can be used, up to 2 instruments.\\n- Only the registered members may perform. No member replacement is allowed.\\n- The organisers do not provide any instruments.\\n\\n## Allowed\\n- Keyboard MIDI as accompaniment track, with no human voice or vocal parts.\\n\\n## Not allowed\\n- MP3 and karaoke tracks.\\n\\n## Judging\\n- Melody, Dynamics, Intonation and Voice Modulation: 40%.\\n- Breath Support: 20%.\\n- Rhythm and Synchronization: 30%.\\n- Expression: 10%.\\n- The judge inspects the keyboard and the accompaniment track on the event day.\\n- The decision of the judges is final and binding."},{"Title":"Bible Verse Writing","Source":"Bible Verse Writing guidelines","Sections":{"About":["One participant per unit."],"TimeAndFormat":["The writing time is 12 minutes."],"Rules":["A booklet of Bible verses is sent to the Unit Secretaries on {{MaterialsDate}}.","Marks are given for correctly written verses with the reference, as in the booklet.","There is no partial marking and no negative marking for wrong answers.","The organisers give writing sheets at the venue. Participants bring their own pens.","The participant must use the booklet format: the Bible reference, then the verse. Example: Hebrews 13:6 - So we say with confidence, \\"The Lord is my helper; I will not be afraid. What can mere mortals do to me?\\"."],"Allowed":["The verses may be written in any order, not the order of the booklet."],"NotAllowed":null,"Judging":["The verse must be complete and accurate, with the reference as in the booklet.","Punctuation marks are taken into consideration.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n\\n## Time and format\\n- The writing time is 12 minutes.\\n\\n## Rules\\n- A booklet of Bible verses is sent to the Unit Secretaries on {{MaterialsDate}}.\\n- Marks are given for correctly written verses with the reference, as in the booklet.\\n- There is no partial marking and no negative marking for wrong answers.\\n- The organisers give writing sheets at the venue. Participants bring their own pens.\\n- The participant must use the booklet format: the Bible reference, then the verse. Example: Hebrews 13:6 - So we say with confidence, \\"The Lord is my helper; I will not be afraid. What can mere mortals do to me?\\".\\n\\n## Allowed\\n- The verses may be written in any order, not the order of the booklet.\\n\\n## Judging\\n- The verse must be complete and accurate, with the reference as in the booklet.\\n- Punctuation marks are taken into consideration.\\n- The decision of the judges is final and binding."},{"Title":"Poster Making","Source":"Poster Making guidelines","Sections":{"About":["One participant per unit."],"TimeAndFormat":["The topic is given on 31 August 2025, 20 minutes before the event starts.","Participants have 60 minutes (1 hour) to make the poster."],"Rules":["Original handmade posters are encouraged.","The organisers give A4 cartridge sheets, so all entries have the same format.","Participants write only their chest number on the sheet. They must not write their name or their parish name.","Participants bring their own materials, such as paints, brushes, pencils or other drawing tools."],"Allowed":["Participants may bring their own painting boards."],"NotAllowed":["Phones are not allowed inside the event venue."],"Judging":["Originality: 40%.","Creativity: 40%.","Delivery of the message: 20%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n\\n## Time and format\\n- The topic is given on 31 August 2025, 20 minutes before the event starts.\\n- Participants have 60 minutes (1 hour) to make the poster.\\n\\n## Rules\\n- Original handmade posters are encouraged.\\n- The organisers give A4 cartridge sheets, so all entries have the same format.\\n- Participants write only their chest number on the sheet. They must not write their name or their parish name.\\n- Participants bring their own materials, such as paints, brushes, pencils or other drawing tools.\\n\\n## Allowed\\n- Participants may bring their own painting boards.\\n\\n## Not allowed\\n- Phones are not allowed inside the event venue.\\n\\n## Judging\\n- Originality: 40%.\\n- Creativity: 40%.\\n- Delivery of the message: 20%."},{"Title":"Street Play","Source":"Street Play guidelines (code SP)","Sections":{"About":["Competition code: SP.","The play must focus on a relevant social message or theme."],"TimeAndFormat":["The maximum time is 9 minutes, including setup time. A warning bell rings at the 8th minute.","Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.","There is no limit on the number of scenes or themes, but the play must stay within the time limit."],"Rules":["A team has at least 5 and at most 20 participants.","The play can be in English, Hindi, Malayalam or a mix of these three languages.","The theme, any scene or dialogue must not be against any person or community.","A street play must stay a street play. It must not turn into a musical act or choreography. The judges of the day take the final decision on this."],"Allowed":["General props such as dupattas, steel plates, spoons and placards.","Teams may use any two of these instruments, only if needed: percussion instrument, manjeera, harmonica, melodica, tambourine, cymbals, harmonium."],"NotAllowed":["Costly costumes.","Electronic instruments."],"Judging":["Conceptualization of narrative and originality: 20%.","Production: 15%.","Acting (bodily movement, gestures, facial expression): 30%.","Dialogue delivery (effective dialogues, slogans, narratives): 20%.","Social message delivered: 15%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Competition code: SP.\\n- The play must focus on a relevant social message or theme.\\n\\n## Time and format\\n- The maximum time is 9 minutes, including setup time. A warning bell rings at the 8th minute.\\n- Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.\\n- There is no limit on the number of scenes or themes, but the play must stay within the time limit.\\n\\n## Rules\\n- A team has at least 5 and at most 20 participants.\\n- The play can be in English, Hindi, Malayalam or a mix of these three languages.\\n- The theme, any scene or dialogue must not be against any person or community.\\n- A street play must stay a street play. It must not turn into a musical act or choreography. The judges of the day take the final decision on this.\\n\\n## Allowed\\n- General props such as dupattas, steel plates, spoons and placards.\\n- Teams may use any two of these instruments, only if needed: percussion instrument, manjeera, harmonica, melodica, tambourine, cymbals, harmonium.\\n\\n## Not allowed\\n- Costly costumes.\\n- Electronic instruments.\\n\\n## Judging\\n- Conceptualization of narrative and originality: 20%.\\n- Production: 15%.\\n- Acting (bodily movement, gestures, facial expression): 30%.\\n- Dialogue delivery (effective dialogues, slogans, narratives): 20%.\\n- Social message delivered: 15%.\\n- The decision of the judges is final and binding."},{"Title":"Bible Quiz","Source":"Bible Quiz guidelines (code BQ)","Sections":{"About":["Competition code: BQ.","Each unit has one team of 2 members."],"TimeAndFormat":["The quiz has 2 rounds.","Round 1 is the qualifying round: off-stage, written, multiple choice, 20 minutes.","Round 2 is the final round: on stage, as directed by the Quiz Master. The Quiz Master decides the pattern and format of the final round."],"Rules":["The Bible to refer to is the New International Version (NIV) or the Good News Bible.","The syllabus is given on {{MaterialsDate}}. It has portions from the New Testament, the Old Testament, Church History and Current Affairs.","Round 1 has 30 questions of 1 mark each. There is no negative marking for wrong answers.","The top five teams from the qualifying round go to the final round."],"Allowed":null,"NotAllowed":null,"Judging":["The decision of the Quiz Master is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Competition code: BQ.\\n- Each unit has one team of 2 members.\\n\\n## Time and format\\n- The quiz has 2 rounds.\\n- Round 1 is the qualifying round: off-stage, written, multiple choice, 20 minutes.\\n- Round 2 is the final round: on stage, as directed by the Quiz Master. The Quiz Master decides the pattern and format of the final round.\\n\\n## Rules\\n- The Bible to refer to is the New International Version (NIV) or the Good News Bible.\\n- The syllabus is given on {{MaterialsDate}}. It has portions from the New Testament, the Old Testament, Church History and Current Affairs.\\n- Round 1 has 30 questions of 1 mark each. There is no negative marking for wrong answers.\\n- The top five teams from the qualifying round go to the final round.\\n\\n## Judging\\n- The decision of the Quiz Master is final and binding."},{"Title":"Essay Writing","Source":"Essay Writing guidelines","Sections":{"About":["One participant per unit.","The topic may be Biblical or moral in nature."],"TimeAndFormat":["Participants have 45 minutes to finish the essay.","All answer sheets are collected at the end of the time limit. No extra time is given for editing or rewriting.","The topic is shared at the registration desk during registration."],"Rules":["The essay must be written entirely during the competition. Participants may not use any pre-written material.","The essay must be handwritten by the participant on the sheets given by the organisers.","There is no minimum word limit, but the essay must not be longer than 1000 words.","The chest number is written in the top right corner of each page. Participants must not write their name or any identifying information on the answer sheets.","Participants bring their own black or blue pens.","Any breaking of these rules leads to disqualification."],"Allowed":null,"NotAllowed":["Plagiarism or use of previously published content leads to immediate disqualification.","Personal notebooks or papers.","Pencils, white ink or correction fluid.","Electronic devices, books and reference materials inside the venue. Phones must be switched off or silent and handed to the volunteers at the start."],"Judging":["Content and Originality: 40%.","Relevance and Biblical application: 40%.","Structure and Overall Impression: 20%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n- The topic may be Biblical or moral in nature.\\n\\n## Time and format\\n- Participants have 45 minutes to finish the essay.\\n- All answer sheets are collected at the end of the time limit. No extra time is given for editing or rewriting.\\n- The topic is shared at the registration desk during registration.\\n\\n## Rules\\n- The essay must be written entirely during the competition. Participants may not use any pre-written material.\\n- The essay must be handwritten by the participant on the sheets given by the organisers.\\n- There is no minimum word limit, but the essay must not be longer than 1000 words.\\n- The chest number is written in the top right corner of each page. Participants must not write their name or any identifying information on the answer sheets.\\n- Participants bring their own black or blue pens.\\n- Any breaking of these rules leads to disqualification.\\n\\n## Not allowed\\n- Plagiarism or use of previously published content leads to immediate disqualification.\\n- Personal notebooks or papers.\\n- Pencils, white ink or correction fluid.\\n- Electronic devices, books and reference materials inside the venue. Phones must be switched off or silent and handed to the volunteers at the start.\\n\\n## Judging\\n- Content and Originality: 40%.\\n- Relevance and Biblical application: 40%.\\n- Structure and Overall Impression: 20%.\\n- The decision of the judges is final and binding."},{"Title":"Orthodox Apologetics","Source":"Orthodox Apologetics guidelines","Sections":{"About":["One participant per unit.","The presentation is meant to show the participant's ability to build deep knowledge of the topic, to research it thoroughly and to present it well."],"TimeAndFormat":["Each presentation is 10 minutes: 8 minutes of presenting and 2 minutes of questions and answers.","The presentation must not exceed 8 minutes. A warning bell rings at the 7th minute. Going over loses 1 mark for every 10 seconds.","There is no negative marking for going over the 2 minutes of questions. Long or off-topic answers are stopped by the judge or the expert panel.","The topic is given on {{MaterialsDate}}.","The presentation file must reach the Diocesan Committee by {{PptDeadline}} through a Google form link shared in the participants' WhatsApp group."],"Rules":["The presentation is made in PPT and presented by the participant.","Two questions are asked of each participant: one by the judges and one by the expert panel.","A participant can prepare at most 10 slides, not counting the title slide and the thank you slide.","Units can help to prepare the PPT, but only the registered participant presents.","The content and delivery can be in English, Hindi or Malayalam."],"Allowed":null,"NotAllowed":["Content that hurts the sentiments of any religion or community, or is anti-Biblical or anti-Church."],"Judging":["The event is marked out of 100.","Content: 30%.","Relevance and Biblical application: 20%.","Confidence and Presentation: 20%.","Slide Creativity: 10%.","Questions: 20%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n- The presentation is meant to show the participant's ability to build deep knowledge of the topic, to research it thoroughly and to present it well.\\n\\n## Time and format\\n- Each presentation is 10 minutes: 8 minutes of presenting and 2 minutes of questions and answers.\\n- The presentation must not exceed 8 minutes. A warning bell rings at the 7th minute. Going over loses 1 mark for every 10 seconds.\\n- There is no negative marking for going over the 2 minutes of questions. Long or off-topic answers are stopped by the judge or the expert panel.\\n- The topic is given on {{MaterialsDate}}.\\n- The presentation file must reach the Diocesan Committee by {{PptDeadline}} through a Google form link shared in the participants' WhatsApp group.\\n\\n## Rules\\n- The presentation is made in PPT and presented by the participant.\\n- Two questions are asked of each participant: one by the judges and one by the expert panel.\\n- A participant can prepare at most 10 slides, not counting the title slide and the thank you slide.\\n- Units can help to prepare the PPT, but only the registered participant presents.\\n- The content and delivery can be in English, Hindi or Malayalam.\\n\\n## Not allowed\\n- Content that hurts the sentiments of any religion or community, or is anti-Biblical or anti-Church.\\n\\n## Judging\\n- The event is marked out of 100.\\n- Content: 30%.\\n- Relevance and Biblical application: 20%.\\n- Confidence and Presentation: 20%.\\n- Slide Creativity: 10%.\\n- Questions: 20%."},{"Title":"Extempore","Source":"Extempore guidelines","Sections":{"About":["One participant per unit.","The topic is socio-religious and is given on the spot.","The speech is meant to show the participant's ability to form a point of view on the topic and to speak without preparation within a limited time."],"TimeAndFormat":["The speech is 4 minutes, with a strict 15 minutes of preparation time. A warning bell rings at 3 minutes 30 seconds.","Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks."],"Rules":["The speech can be in English or Malayalam.","During preparation the organisers give a sheet of paper, a pen and a Bible."],"Allowed":["Speech notes for reference, if their use is unobtrusive and does not affect the participant's eye contact with the audience."],"NotAllowed":["Phones are strictly prohibited."],"Judging":["Content: 30%.","Relevance and Biblical Application: 40%.","Presentation and Confidence: 30%.","The decision of the judges is final and binding."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- One participant per unit.\\n- The topic is socio-religious and is given on the spot.\\n- The speech is meant to show the participant's ability to form a point of view on the topic and to speak without preparation within a limited time.\\n\\n## Time and format\\n- The speech is 4 minutes, with a strict 15 minutes of preparation time. A warning bell rings at 3 minutes 30 seconds.\\n- Time over the limit loses marks: up to 15 seconds -3 marks, 15 to 30 seconds -5 marks, above 30 seconds -7 marks.\\n\\n## Rules\\n- The speech can be in English or Malayalam.\\n- During preparation the organisers give a sheet of paper, a pen and a Bible.\\n\\n## Allowed\\n- Speech notes for reference, if their use is unobtrusive and does not affect the participant's eye contact with the audience.\\n\\n## Not allowed\\n- Phones are strictly prohibited.\\n\\n## Judging\\n- Content: 30%.\\n- Relevance and Biblical Application: 40%.\\n- Presentation and Confidence: 30%.\\n- The decision of the judges is final and binding."},{"Title":"Solo Instrumental Piano/Keyboard","Source":"Solo Instrumental guidelines","Sections":{"About":["Solo Instrumental has 2 categories: Category 1 Piano/Keyboard and Category 2 String instruments. Each unit sends 1 participant for each category.","Participants get one music sample, a short segment of 30 to 60 seconds. They keep its core melodic and harmonic structure and reinterpret it with their own flavour, such as a genre twist, style changes or tempo changes.","The sample is given to the participants two days before the event."],"TimeAndFormat":["Each performance is 4 minutes. A warning bell rings at 3 minutes 30 seconds."],"Rules":["The reinterpretation must clearly show identifiable parts of the original sample. The original chords must be present.","Any instrument, classical or modern, can be used."],"Allowed":["Participants can change the genre or style (for example turn a classical piece into jazz, or a rock track into an ambient soundscape), and change the tempo, instrumentation and articulation."],"NotAllowed":["Only solo performances are allowed. No backing tracks or pre-recorded accompaniment."],"Judging":["Originality of the composition: 15%.","Creative expression: 25%.","Rhythm: 25%.","Technical skills: 35%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Solo Instrumental has 2 categories: Category 1 Piano/Keyboard and Category 2 String instruments. Each unit sends 1 participant for each category.\\n- Participants get one music sample, a short segment of 30 to 60 seconds. They keep its core melodic and harmonic structure and reinterpret it with their own flavour, such as a genre twist, style changes or tempo changes.\\n- The sample is given to the participants two days before the event.\\n\\n## Time and format\\n- Each performance is 4 minutes. A warning bell rings at 3 minutes 30 seconds.\\n\\n## Rules\\n- The reinterpretation must clearly show identifiable parts of the original sample. The original chords must be present.\\n- Any instrument, classical or modern, can be used.\\n\\n## Allowed\\n- Participants can change the genre or style (for example turn a classical piece into jazz, or a rock track into an ambient soundscape), and change the tempo, instrumentation and articulation.\\n\\n## Not allowed\\n- Only solo performances are allowed. No backing tracks or pre-recorded accompaniment.\\n\\n## Judging\\n- Originality of the composition: 15%.\\n- Creative expression: 25%.\\n- Rhythm: 25%.\\n- Technical skills: 35%."},{"Title":"Solo Instrumental String","Source":"Solo Instrumental guidelines","Sections":{"About":["Solo Instrumental has 2 categories: Category 1 Piano/Keyboard and Category 2 String instruments. Each unit sends 1 participant for each category.","Participants get one music sample, a short segment of 30 to 60 seconds. They keep its core melodic and harmonic structure and reinterpret it with their own flavour, such as a genre twist, style changes or tempo changes.","The sample is given to the participants two days before the event."],"TimeAndFormat":["Each performance is 4 minutes. A warning bell rings at 3 minutes 30 seconds."],"Rules":["The reinterpretation must clearly show identifiable parts of the original sample. The original chords must be present.","Any instrument, classical or modern, can be used."],"Allowed":["Participants can change the genre or style (for example turn a classical piece into jazz, or a rock track into an ambient soundscape), and change the tempo, instrumentation and articulation."],"NotAllowed":["Only solo performances are allowed. No backing tracks or pre-recorded accompaniment."],"Judging":["Originality of the composition: 15%.","Creative expression: 25%.","Rhythm: 25%.","Technical skills: 35%."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Solo Instrumental has 2 categories: Category 1 Piano/Keyboard and Category 2 String instruments. Each unit sends 1 participant for each category.\\n- Participants get one music sample, a short segment of 30 to 60 seconds. They keep its core melodic and harmonic structure and reinterpret it with their own flavour, such as a genre twist, style changes or tempo changes.\\n- The sample is given to the participants two days before the event.\\n\\n## Time and format\\n- Each performance is 4 minutes. A warning bell rings at 3 minutes 30 seconds.\\n\\n## Rules\\n- The reinterpretation must clearly show identifiable parts of the original sample. The original chords must be present.\\n- Any instrument, classical or modern, can be used.\\n\\n## Allowed\\n- Participants can change the genre or style (for example turn a classical piece into jazz, or a rock track into an ambient soundscape), and change the tempo, instrumentation and articulation.\\n\\n## Not allowed\\n- Only solo performances are allowed. No backing tracks or pre-recorded accompaniment.\\n\\n## Judging\\n- Originality of the composition: 15%.\\n- Creative expression: 25%.\\n- Rhythm: 25%.\\n- Technical skills: 35%."}]`),s=[],r=[{Key:"EventDate",Kind:"date",Label:"Event day",Value:"2025-08-31",Source:"General Guidelines 1"},{Key:"FormReleaseDate",Kind:"date",Label:"Registration form sent to Unit Secretaries",Value:"2025-07-13",Source:"General Guidelines 2"},{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register, 11:59 PM",Value:"2025-08-17",Source:"General Guidelines 3 and 4"},{Key:"MaterialsDate",Kind:"date",Label:"Bible verse booklet, Bible Quiz syllabus and Orthodox Apologetics topic given",Value:"2025-07-13",Source:"Bible Verse Writing 3, Bible Quiz 3, Orthodox Apologetics 10"},{Key:"PptDeadline",Kind:"date",Label:"Orthodox Apologetics PPT due",Value:"2025-08-25",Source:"Orthodox Apologetics 9"},{Key:"RulesQueryDeadline",Kind:"text",Label:"Last time to send rules queries",Value:"1 August 2025, 8:30 PM",Source:"Final page"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"St. Thomas School",Address:"",City:"Faridabad",MapUrl:"",Directions:""},Source:"General Guidelines 1"},{Key:"RegistrationEmail",Kind:"contact",Label:"Diocesan Committee email for registration and queries",Value:{Name:"Diocesan MGOCSM Committee",Role:"Registration",Phone:"",WhatsApp:"",Email:"mgocsmdiocese.delhi@gmail.com"},Source:"General Guidelines 3"},{Key:"SecretaryContact",Kind:"contact",Label:"Diocesan MGOCSM Secretary",Value:{Name:"Ms. Kesiya Kunjumon",Role:"Diocesan MGOCSM Secretary",Phone:"",WhatsApp:"",Email:""},Source:"General Guidelines 17"},{Key:"CulturalSecretaryContact",Kind:"contact",Label:"Cultural Secretary",Value:{Name:"Ms. Celina Binu",Role:"Cultural Secretary",Phone:"",WhatsApp:"",Email:""},Source:"General Guidelines 17"},{Key:"Schedule",Kind:"text",Label:"Tentative schedule printed in the circular",Value:"Tentative schedule: Solo Song 10:30 to 12:00, Orthodox Apologetics 10:30 to 12:00, Essay Writing 11:00 to 12:00, Poster Making 11:00 to 12:00, Bible Verse Writing 12:00 to 12:12, Bible Quiz qualifying round 12:12 to 12:32, Group Song 12:32 to 1:45, lunch 1:45 to 2:30, Mono Act 2:30 to 3:30, Bible Quiz final round 2:30 to 3:30, Solo Instrumental 3:30 to 4:30, Extempore 3:30 to 4:30, Street Play 4:30 to 6:00, Photography 10:30 to 3:30.",Source:"Tentative schedule page"}],l=[{Claim:"Rules, eligibility, registration steps, dates, contacts and championship points of Olive 2025.",SourceType:"Primary - the event's own rules document",Source:"Olive 2025 - Celebration of Talents, Rules and Regulations (MGOCSM Delhi Diocese Committee)",Url:"https://www.scribd.com/document/905254873/Olive-2025-Rules-and-Regulations"}],c={TemplateKey:e,Year:2025,Note:t,Page:n,ParticipantTypes:i,AgeGroups:a,Competitions:o,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{a as AgeGroups,s as CompetitionAgeGroups,o as Competitions,l as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,r as Variables,h as Year,c as default};
